import{_ as t,c as i,o as s,a2 as o}from"./chunks/framework.jqDK1qTK.js";const d=JSON.parse('{"title":"GEP-0038: Autoscaling PersistentVolumeClaims","description":"","frontmatter":{"github_repo":"https://github.com/gardener/documentation","github_subdir":"website/community/steering/technical","params":{"github_branch":"master"},"path_base_for_github_subdir":{"from":"content/community/steering/technical/0038-autoscaling-persistentvolumeclaims.md","to":"0038-autoscaling-persistentvolumeclaims.md"},"title":"GEP-0038: Autoscaling PersistentVolumeClaims","prev":false,"next":false},"headers":[],"relativePath":"community/steering/technical/0038-autoscaling-persistentvolumeclaims/index.md","filePath":"community/steering/technical/0038-autoscaling-persistentvolumeclaims.md","lastUpdated":null}'),r={name:"community/steering/technical/0038-autoscaling-persistentvolumeclaims/index.md"};function n(l,e,a,u,c,g){return s(),i("div",null,e[0]||(e[0]=[o('<h1 id="gep-0038-autoscaling-persistentvolumeclaims" tabindex="-1">GEP-0038: Autoscaling PersistentVolumeClaims <a class="header-anchor" href="#gep-0038-autoscaling-persistentvolumeclaims" aria-label="Permalink to &quot;GEP-0038: Autoscaling PersistentVolumeClaims&quot;">​</a></h1><ul><li>📌 <strong>GEP Tracking Issue:</strong> <a href="https://github.com/gardener/enhancements/issues/38" target="_blank" rel="noreferrer">https://github.com/gardener/enhancements/issues/38</a></li><li>📖 <strong>GEP Link:</strong> <a href="https://github.com/gardener/enhancements/tree/main/geps/0038-autoscaling-persistentvolumeclaims" target="_blank" rel="noreferrer">https://github.com/gardener/enhancements/tree/main/geps/0038-autoscaling-persistentvolumeclaims</a></li><li>✍🏻 <strong>Author(s):</strong> <a href="https://github.com/plkokanov" target="_blank" rel="noreferrer">@plkokanov</a> (Plamen Kokanov), <a href="https://github.com/Kostov6" target="_blank" rel="noreferrer">@Kostov6</a> (Viktor Kostov)</li><li>🗓️ <strong>Presentation:</strong> 2026-02-03, 15:00 - 16:00 CET and 2026-02-04, 10:00 - 11:00 CET</li><li>🎥 <strong>Recording:</strong> <a href="https://youtu.be/JJmFiZvuMBY" target="_blank" rel="noreferrer">https://youtu.be/JJmFiZvuMBY</a></li><li>👨‍⚖️ <strong>Decisions &amp; Agreements:</strong><ul><li><strong>Seed settings scope</strong><ul><li>Provider-specific settings (e.g., max capacity, cooldown duration) will be moved out of seed settings.</li><li>These will be implemented via <strong>provider extension webhooks</strong> to reduce API surface and ops overhead.</li><li>Rationale: provider-specific logic should not live in generic Gardener APIs.</li><li>Along this way, <code>.spec.volume.minimumSize</code> will be <strong>deprecated</strong> and moved into a webhook as well.</li></ul></li><li><strong>Scale-up failure handling</strong><ul><li>Behavior depends on the CSI driver.</li><li>Kubernetes ≥1.34 supports <strong>rollback of failed resize operations</strong> which can be used.</li><li>Evicting pods after a failed resize was considered, though this would require a strategy field in the PVCA API and exposure via seed settings.</li><li><strong>Decision</strong>: No explicit <em>Evict</em> strategy; rely on kubelet conditions.</li></ul></li><li><strong>Metrics source</strong><ul><li>HPA/VPA use the Kubernetes metrics API.</li><li>There is <strong>no active upstream work</strong> to expose PVC disk metrics via metrics-server; PVC metrics are still <strong>alpha</strong>.</li><li>PVCA metric queries must be <strong>configurable</strong> to support multiple Kubernetes versions (already foreseen).</li></ul></li><li><strong>Shoot cluster support</strong><ul><li>Supporting shoots is a long-term goal (not in scope for now), but currently blocked by missing metrics (no Prometheus for shoot PVCs).</li><li><strong>Outlook</strong>: <ul><li>Open an upstream Kubernetes proposal to add PVC metrics to the metrics-server.</li><li>This is a prerequisite for shoot support and removes the Prometheus dependency.</li></ul></li></ul></li></ul></li><li>👨‍⚖️ <strong>Documentation Requirements</strong><ul><li><strong>Non-goals</strong><ul><li>PVC downscaling.</li><li>Shoot cluster support (for now).</li></ul></li><li><strong>Downscaling</strong><ul><li>Clearly document why downscaling is not supported.</li></ul></li><li><strong>Testing</strong><ul><li>Metrics-related tests should live in <strong>gardener/gardener</strong>, not in <strong>gardener/pvc-autoscaler</strong>.</li></ul></li><li><strong>ETCD volumes</strong><ul><li>ETCD volumes are out of scope.</li><li>Reason: ETCD teams plan to orchestrate this via <strong>druid</strong>.</li></ul></li><li><strong>API field explanations</strong><ul><li>Clarify fields such as <em>stabilization duration window</em> and others.</li></ul></li><li><strong>Admission considerations</strong><ul><li>Admission webhook for mutating PVCs on creation is <strong>not required</strong> today.</li><li>Existing controllers handle concurrent PVC spec updates correctly.</li><li>An admission component may be needed if downscaling is introduced in the future.</li></ul></li><li><strong>Runtime / operator context</strong><ul><li>Clarify runtime cluster and <strong>gardener-operator</strong> involvement.</li></ul></li><li><strong>IOPS</strong><ul><li>IOPS are <strong>out of scope</strong> for the initial API to avoid bloating it.</li><li>Future support could be via an additional metric source, likely on the StorageClass.</li><li>Current workaround: increase <code>minCapacity</code> to trade storage for performance.</li></ul></li></ul></li></ul>',2)]))}const p=t(r,[["render",n]]);export{d as __pageData,p as default};
